<script setup lang="ts">
import {Head,router,useForm} from '@inertiajs/vue3';
import {ref} from 'vue';
import AppLayout from '../../Layouts/AppLayout.vue';
const props=defineProps<{organization:{id:number;name:string};store:{id:number;name:string};templates:{key:string;subject:string;body:string;enabled:boolean;version:number}[];assets:{public_id:string;title:string;mime:string;created_at:string}[];canManage:boolean}>();
const base=`/organizations/${props.organization.id}/stores/${props.store.id}/affiliate/materials`;
const form=useForm({title:'',file:null as File|null});
const template=ref<string|null>(null);
const mailForm=useForm({subject:'',body:'',enabled:false});
const deleting=ref<string|null>(null);
</script>
<template><Head title="推广素材"/><AppLayout><div class="space-y-6 p-6"><header><h1 class="text-2xl font-bold">推广素材</h1><p class="mt-2 text-slate-500">{{store.name}} · 供已批准的推广者在门户下载。</p></header><form v-if="canManage" class="grid gap-4 rounded-2xl border bg-white p-6 sm:grid-cols-2" @submit.prevent="form.post(base,{forceFormData:true,onSuccess:()=>form.reset()})"><label>素材名称<input v-model="form.title" maxlength="150" required class="mt-2 w-full rounded-xl border-slate-300"></label><label>文件<input type="file" accept=".png,.jpg,.jpeg,.webp,.pdf,.txt" required class="mt-2 block" @change="form.file=($event.target as HTMLInputElement).files?.[0]??null"></label><p class="text-sm text-slate-500">支持图片、PDF 和文本，最大 10 MB。</p><button :disabled="form.processing" class="rounded-xl bg-emerald-700 px-4 py-2 text-white">上传素材</button><p v-for="error in form.errors" :key="error" class="text-red-700">{{error}}</p></form><div class="rounded-2xl border bg-white"><p v-if="!assets.length" class="p-8 text-slate-500">暂无素材。</p><div v-for="asset in assets" :key="asset.public_id" class="flex items-center justify-between border-b p-5 last:border-0"><div><h2 class="font-semibold">{{asset.title}}</h2><p class="text-sm text-slate-500">{{asset.mime}}</p></div><button v-if="canManage" class="text-red-700" @click="deleting=asset.public_id">删除</button></div></div><section v-if="templates.length" class="space-y-4 rounded-2xl border bg-white p-6"><h2 class="text-lg font-bold">通知模板</h2><p class="text-sm text-slate-500">启用后，系统在相应业务事件发生时发送事务邮件。支持 {name} 和 {program}；购后邀请另支持 {invitation_url}，只向同意营销邮件的已购顾客发送。</p><div v-for="item in templates" :key="item.key" class="flex justify-between border-t py-3"><div>{{item.subject}}<small class="ml-2 text-slate-500">{{item.enabled?'已启用':'未启用'}} · v{{item.version}}</small></div><button class="text-emerald-700" @click="template=item.key;Object.assign(mailForm,{subject:item.subject,body:item.body,enabled:item.enabled})">编辑</button></div></section><div v-if="template" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-5"><form class="w-full max-w-xl space-y-4 rounded-2xl bg-white p-6" @submit.prevent="mailForm.put(base.replace('/materials','/notification-templates/')+template,{onSuccess:()=>template=null})"><h2 class="text-lg font-bold">编辑通知</h2><label class="block">主题<input v-model="mailForm.subject" required maxlength="200" class="mt-2 w-full rounded-xl border-slate-300"></label><label class="block">正文<textarea v-model="mailForm.body" required maxlength="10000" rows="6" class="mt-2 w-full rounded-xl border-slate-300" /></label><label><input v-model="mailForm.enabled" type="checkbox"> 启用此模板发送</label><p v-for="error in mailForm.errors" :key="error" class="text-red-700">{{error}}</p><div class="flex justify-end gap-4"><button type="button" @click="template=null">返回</button><button :disabled="mailForm.processing" class="rounded-xl bg-emerald-700 px-4 py-2 text-white">保存模板</button></div></form></div><div v-if="deleting" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40"><div class="space-y-5 rounded-2xl bg-white p-6"><p>删除后，推广者将无法继续下载这份素材。</p><div class="flex justify-end gap-4"><button @click="deleting=null">返回</button><button class="text-red-700" @click="router.delete(`${base}/${deleting}`,{onSuccess:()=>deleting=null})">确认删除</button></div></div></div></div></AppLayout></template>
